{
    int rv = 0;
    scconf_context	*conf = NULL;
    conf = scconf_new(NULL);
    if (!conf)
        return 0;

    if ((rv = scconf_parse_string(conf, (char *)data)) < 0) {
        scconf_free(conf);
        return rv;
    }

    rv = process_conf(profile, conf);
    scconf_free(conf);
    return rv;
