void do_erase(struct sc_profile *profile, sc_card_t *card)
{
    struct sc_pkcs15_card *p15card;

    p15card = sc_pkcs15_card_new();
    p15card->card = card;

    sc_pkcs15init_erase_card(p15card, profile, NULL);
    sc_pkcs15_card_free(p15card);
}

